export type SliceComponentName = keyof SliceComponentPropsMap;
export type SliceDynamicElement = HTMLElement & Record<string, any>;

declare global {
  const slice: SliceBuildApi & Record<string, any>;

  interface Event {
    detail: any;
    key: any;
    request: any;
    waitUntil: any;
    respondWith: any;
    target: any;
    currentTarget: any;
  }

  interface Element {
    querySelector<E extends Element = HTMLElement>(selectors: string): E | null;
    querySelectorAll<E extends Element = HTMLElement>(selectors: string): NodeListOf<E>;
  }
  interface HTMLElement {
    [key: string]: any;
  }
  interface EventTarget {
    [key: string]: any;
  }

  interface SliceBuildApi {
    build<K extends SliceComponentName>(
      name: K,
      props?: SliceComponentPropsMap[K]
    ): Promise<SliceDynamicElement | null>;
  }
}

declare module 'slicejs-web-framework' {
  interface SliceApi {
    build<K extends SliceComponentName>(
      name: K,
      props?: SliceComponentPropsMap[K]
    ): Promise<SliceDynamicElement | null>;
    getComponent<K extends SliceComponentName>(
      componentSliceId: K | `${K}-${string}`
    ): SliceDynamicElement | undefined;
    getComponent<T extends SliceDynamicElement = SliceDynamicElement>(
      componentSliceId: string
    ): T | undefined;
  }
}

export {};
